"""Freeze the inspected concept interpretation before geometry authoring."""
import json
from datetime import datetime, timezone
from pathlib import Path

ROOT=Path(__file__).resolve().parent
VIEWS=['hero','reversehero','front','rear','left','right','top','bottom','clay','clayalt','wire']
DESIGNS={
'sapeornis':(.35,'Sapeornis-inspired broad-winged bird','会鸟灵感宽翼小鸟',
'Compact tawny and cream feathered body, modest short snout, broad spread feathered wings with separated outer primary tips, graduated fan of tail feathers. Small tucked paired feet. Quiet chest, warm brown flight feathers and cream coverts. No crest or long skeletal tail.',
[('ZHENG-2014','https://pmc.ncbi.nlm.nih.gov/articles/PMC4183337/','Discussion paragraph beginning Although Sapeornis: small pygostyle, fan-arranged long rectrices, elongated forelimbs.'),('SERRANO-2017','https://pmc.ncbi.nlm.nih.gov/articles/PMC5550970/','Results wing shape; Wing outline reconstruction, specimen DNHM-3078. Broad high-lift wing interpretation; not copying outline measurements.')],
'Both concept views are oblique, not calibrated orthographic. Author full bilateral wings, feather thickness and rounded underside; do not claim an exact count of fossil feathers. Soaring pose and wing span are artistic approximations.'),
'longirostravis':(.18,'Longirostravis-inspired long-snouted bird','长嘴鸟灵感小鸟',
'Delicate olive and cream body standing on two separate feet; long slender tapering snout gently curves downward. Folded layered wings and two narrow long tail feathers. Restrained rust cheek, small dark eyes. Shorten exaggerated ImageGen snout to around head length; no thick duck bill or enormous curlew beak.',
[('HOU-2004','https://pmc.ncbi.nlm.nih.gov/articles/PMC4382005/','Original paper DOI 10.1007/s00114-003-0489-1, abstract and indexed descriptive paragraph Fig2A/B: slender tapering 35mm rostrum/mandible gently curves down; tip-restricted teeth.'),('OCONNOR-2012','https://pmc.ncbi.nlm.nih.gov/articles/PMC3758748/','Tail-feather discussion lists Longirostravis among taxa with paired elongate rectrices; only indexed passage available.')],
'Concept side views agree on folded wing and two feet but beak too strongly curved/long: deliberately reduce. Teeth and detailed skeletal anatomy are below this stylized prop scope, not a toothless scientific claim. Tail feather breadth is artistic; no diet or behaviour certainty asserted.'),
'dunbaria':(.035,'Dunbaria-inspired band-winged insect','Dunbaria灵感带纹古昆虫',
'Four broad tapering main wings in two distinct pairs, plus two MUCH smaller hardened heart-shaped prothoracic lobes forward of main wings, six jointed legs, segmented abdomen, slender downward-forward beak, paired antennae and long trailing cerci. Ochre thorax, honey cream wings with coherent brown cross bands; sparse raised veins. Never six equal-sized true wings.',
[('KUKALOVA-PECK-1971','https://onlinelibrary.wiley.com/doi/10.1155/1971/84672','The Structure of Dunbaria, Psyche78:306-318; author-uploaded full text consulted at https://www.researchgate.net/publication/40632035_The_Structure_of_Dunbaria_Palaeodictyoptera ; thorax description MCZ3057 and systematic description: sclerotized cordate prothoracic lobes do not overlap forewings; long paired cerci.'),('PROKOP-2018','https://pubmed.ncbi.nlm.nih.gov/29635036/','Original abstract, wing-base interpretation in D.quinquefasciata; warns that historical fine articulation interpretation is debated.')],
'Concept side hides far wings/legs. Build all four main wings and exactly six walking legs. Make small front lobes cordate and isolated rather than an equal third wing pair. Sparse generic veins, artistic bands and approximate scale; no exact sex/species or venation reconstruction asserted.'),
'chimerarachne':(.003,'Chimerarachne-inspired tailed arachnid','奇美拉蛛灵感尾鞭蛛形动物',
'Low domed front body, narrow waist, oval visibly segmented abdomen and long slender gently curved whip-like tail; eight articulated walking legs in four pairs, two smaller simple pedipalps at front, subtle rear underside spinneret projections. Warm walnut/russet/sand palette, modest natural dark eyes. No scorpion sting, pincers, horror spikes or web.',
[('WANG-2018','https://www.nature.com/articles/s41559-017-0449-3','Original abstract and figure-list3: segmented opisthosoma, whip-like telson, well-defined spinnerets; position relative to spiders/uraraneids uncertain. Body proportions approximate; primary figure pixels not available via local download (403).')],
'Concept pedipalps too large and some legs overlap. Author exactly eight well-separated walking legs plus visibly shorter simple pedipalps; smooth a few abdomen plate transitions, preserve segmentation. Spinnerets simplified. Tail curvature, colour and eye placement artistic; no sex-exact or taxonomic placement assertion.')}

def main():
    now=datetime.now(timezone.utc).isoformat()
    for row,(slug,(length,label,zh,design,sources,resolution)) in enumerate(DESIGNS.items(),1):
        d=ROOT/slug/'r001';d.mkdir(parents=True,exist_ok=True)
        config=dict(asset_id=slug,revision='r001',length_m=length,seed=19,max_triangles=16000,max_materials=8,max_primitives=160,soft_glb_bytes=1000000,surface_profile='palette-only',mount_origin='flight-body center' if slug=='sapeornis' else 'floor contact center',role='supporting scene life; typical128px, inspectable512px',normal_visible_copies=8,stress_visible_copies=32,runtime_target='Three.js0.180.0; parent independent parse/GPU/scene QA pending')
        brief=dict(asset_id=slug,revision='r001',frozen_at=now,label=label,label_zh=zh,scope='Original stylized child-friendly scene prop inspired by inventory taxon. Not scientific reconstruction. No inventory approval or publication.',design=design,concept='../../concept-original.png',concept_row=row,concept_interpretation=resolution,axes=dict(forward='-Y',up='+Z',meters=True),budgets=config,required_views=VIEWS,turntable_frames=0,coverage='Eight geometric directions plus clay/alternate key/wire. Static candidate only; pending independent QA.',critical_obligations=['Independent identifying silhouette; real body volume and closed thick appendages','Anatomical paired landmark counts stated in design','Source, export and separately executed rebuild parity','Exact exported GLB multi-angle pixels inspected','Honest stylized claim limits and pending external gates'],pending=['independent visual/factual/specification QA','Three.js parse/GPU/populated scene QA'])
        refs=dict(schema_version=1,asset_id=slug,sources=[dict(id=s,url=u,location=l,accessed='2026-10-19',use='consulted-only; no copied image, palette, code or geometry',creator_license='Reference remains with original authors; no redistribution/reuse rights asserted',limitations='Only described features support the narrow inspired design; full anatomical reconstruction not claimed') for s,u,l in sources],external_claim_scope='Stylized inspired prop; artistic colours and approximate dimensions; no fossil-exact species assertion')
        for name,obj in [('brief.json',brief),('build-config.json',config),('references.json',refs)]:
            (d/name).write_text(json.dumps(obj,ensure_ascii=False,indent=2)+'\n')
        (d/'brief.md').write_text(f'# {label}\n\nFrozen {now}, after real ImageGen pixel inspection, before generator authoring.\n\n{design}\n\n{resolution}\n\n{brief["scope"]}\n\nClosed volumetric loft body, thick biconvex feathers/wings, tapered multi-station limb tubes; semantic editable parts. No image textures or planes. Standard/None exposure0 gamma1, neutral common renderer; all eleven exact-GLB views.\n\nNominal art length parameter {length}m; measured export bounds authoritative. Seed19. Blender4.3.2; portable embedded static GLB, flat normals, region-based original palette.\n\nCC BY4.0 Leon Made This / s010s; executable code MIT. Independent QA, browser GPU and populated-scene evidence pending parent.\n')
    (ROOT/'brief-freeze-record.json').write_text(json.dumps(dict(frozen_at=now,geometry_started=False,assets=list(DESIGNS),basis='Inspected original concept at recorded clock time; sources consulted only'),indent=2)+'\n')

if __name__=='__main__':main()
